// Financial Math Helpers
function calculateNPV(rate, cashflows) {
    let npv = 0;
    for (let t = 0; t < cashflows.length; t++) {
        npv += cashflows[t] / Math.pow(1 + rate, t);
    }
    return npv;
}

function calculateIRR(cashflows) {
    let hasPositive = false;
    let hasNegative = false;
    for (let val of cashflows) {
        if (val > 0) hasPositive = true;
        if (val < 0) hasNegative = true;
    }
    if (!hasPositive || !hasNegative) return null;
    
    let guessMin = -0.999;
    let guessMax = 2.0;
    let fMin = calculateNPV(guessMin, cashflows);
    let fMax = calculateNPV(guessMax, cashflows);
    
    for (let i = 0; i < 20; i++) {
        if (fMin * fMax <= 0) break;
        guessMax *= 1.5;
        fMax = calculateNPV(guessMax, cashflows);
    }
    
    if (fMin * fMax > 0) return null;
    
    let rate = 0;
    for (let i = 0; i < 150; i++) {
        rate = (guessMin + guessMax) / 2.0;
        let fRate = calculateNPV(rate, cashflows);
        if (Math.abs(fRate) < 1e-11) return rate;
        
        if (fMin * fRate < 0) {
            guessMax = rate;
            fMax = fRate;
        } else {
            guessMin = rate;
            fMin = fRate;
        }
    }
    return rate;
}

// Payback finder (cumulative cashflow index)
function calculatePaybackIndex(cashflows, initialInvestment) {
    let cumulative = -initialInvestment;
    for (let t = 1; t < cashflows.length; t++) {
        cumulative += cashflows[t];
        if (cumulative >= 0) {
            return t; 
        }
    }
    return ">20";
}

// Main financial evaluation engine (Correct standard accounting rules)
function runEvaluation() {
    const totalCost = (state.capacity * state.unitCost) + state.otherCost;
    const totalSubsidy = state.govtSubsidy + state.extraSubsidy;
    const netCost = totalCost - totalSubsidy;
    
    // Apply Northern premium if applicable
    const cityData = citiesDatabase[state.city];
    const isNorthern = cityData ? cityData.isNorthern : false;
    const effectiveFitRate = (isNorthern) ? state.fitRate * 1.15 : state.fitRate;
    
    // Module recycling fee (amortized over 10 years)
    const recyclingTotal = (state.recyclingRate * state.capacity) / 10000;
    const annualRecycling = recyclingTotal / 10;
    
    // Correct Depreciation: recycling fee adds to asset value, depreciated standardly
    const recyclingYear10 = -annualRecycling;
    const depAdjustment = -recyclingYear10; // Not divided by 10 twice (Excel bug removed)
    
    // Equal Principal Repayment Loan Schedule (if enabled)
    const activeLoanPct = state.loanEnable ? state.loanPct : 0.0;
    const loanAmount = totalCost * (activeLoanPct / 100);
    const principalRepay = state.loanYears > 0 ? loanAmount / state.loanYears : 0;
    
    // Setup arrays
    let tableData = [];
    let projectCashflows = [-netCost];
    let projectGrossCashflows = [-netCost];
    let equityCashflows = [-(netCost - loanAmount)];
    
    for (let t = 1; t <= 20; t++) {
        const yearDegrad = Math.pow(0.992, t - 1);
        
        // 1. Generation & Revenue
        const yieldKwh = state.capacity * (state.sunHours * 365) * state.generationFactor * yearDegrad;
        const revenue = (yieldKwh * effectiveFitRate) / 10000; 
        
        // 2. Expenses
        const omRate = (t <= 5) ? state.omRate1_5 : state.omRate6_20;
        const omCost = revenue * (omRate / 100); 
        
        const meterRentVal = state.meterRent;
        const recycling = (t <= 10) ? annualRecycling : 0;
        
        // Depreciation
        let dep = 0;
        if (t <= 10) {
            dep = totalCost / state.depreciationYears;
        } else if (t <= state.depreciationYears) {
            dep = (totalCost / state.depreciationYears) + depAdjustment;
        } else {
            dep = depAdjustment; 
        }
        
        // General Overhead and Insurance (based on total cost)
        const overhead = totalCost * (state.managementRate / 100);
        const insurance = totalCost * (state.insuranceRate / 100);
        
        // Loan Interest
        let interest = 0;
        let loanRepay = 0;
        if (state.loanEnable && t <= state.loanYears && loanAmount > 0) {
            const debtStart = loanAmount - (t - 1) * principalRepay;
            interest = debtStart * (state.loanRate / 100);
            loanRepay = principalRepay;
        }
        
        // 3. Pre-tax Profit (Income Statement)
        // Recycling fee is standard tax deductible expense
        const totalOperatingCost = omCost + meterRentVal + recycling + dep + overhead + insurance;
        const preTaxProfit = revenue - totalOperatingCost - interest;
        
        // Tax (20%)
        const tax = preTaxProfit > 0 ? preTaxProfit * (state.taxRate / 100) : 0;
        const netIncome = preTaxProfit - tax;
        
        // 4. Cash Flow (Project - 100% Equity)
        const preTaxProfitNoLoan = revenue - totalOperatingCost;
        const taxNoLoan = preTaxProfitNoLoan > 0 ? preTaxProfitNoLoan * (state.taxRate / 100) : 0;
        const netIncomeNoLoan = preTaxProfitNoLoan - taxNoLoan;
        const projectCF = netIncomeNoLoan + dep; // Recycling is cash outlay, deducted in preTaxProfitNoLoan and not added back. Correct.
        
        // Project Cash Flow without O&M and Tax (X維運)
        const projectGrossCF = revenue;
        
        // 5. Cash Flow (Equity - With Loan)
        const equityCF = netIncome + dep - loanRepay;
        
        tableData.push({
            year: t,
            revenue: revenue,
            omCost: omCost,
            meterRent: meterRentVal,
            recycling: recycling,
            dep: dep,
            overhead: overhead,
            insurance: insurance,
            interest: interest,
            preTax: preTaxProfit,
            tax: tax,
            netIncome: netIncome,
            projectCF: projectCF,
            projectGrossCF: projectGrossCF,
            equityCF: equityCF,
            loanRepay: loanRepay
        });
        
        projectCashflows.push(projectCF);
        projectGrossCashflows.push(projectGrossCF);
        equityCashflows.push(equityCF);
    }
    
    // Calculations for KPIs
    const sumProjectCashflows = tableData.reduce((sum, row) => sum + row.projectCF, 0);
    
    // 20-Year Profit
    const netProfit = sumProjectCashflows - netCost;
    
    // ROI = 20-Year Net Profit / Net out of pocket Cost (Correct standard accounting)
    const roi = netProfit / netCost;
    
    // IRRs
    const irrEquity = calculateIRR(projectCashflows);
    const irrLoan = state.loanEnable ? calculateIRR(equityCashflows) : null;
    
    // Paybacks
    const paybackWithOM = calculatePaybackIndex(projectCashflows.slice(1), netCost);
    const paybackWithoutOM = calculatePaybackIndex(projectGrossCashflows.slice(1), netCost);
    
    // Carbon Reduction (0.495 kg CO2 / kWh, 12 kg CO2 / tree)
    const totalKwh = tableData.reduce((sum, row) => sum + (row.revenue * 10000 / effectiveFitRate), 0);
    const co2ReductionKg = totalKwh * 0.495;
    const co2ReductionTons = co2ReductionKg / 1000;
    const equivalentTrees = co2ReductionKg / 12 / 20; 
    
    return {
        totalCost,
        totalSubsidy,
        netCost,
        tableData,
        projectCashflows,
        projectGrossCashflows,
        equityCashflows,
        netProfit,
        roi,
        irrEquity,
        irrLoan,
        paybackWithOM,
        paybackWithoutOM,
        co2ReductionTons,
        equivalentTrees
    };
}

// Synchronize range sliders and number inputs
function bindInputs(sliderId, numberId, stateProp, decimalPlaces = 2) {
    const slider = document.getElementById(sliderId);
    const num = document.getElementById(numberId);
    
    slider.addEventListener('input', (e) => {
        let val = parseFloat(e.target.value);
        state[stateProp] = val;
        num.value = val.toFixed(decimalPlaces);
        updateDashboard();
    });
    
    num.addEventListener('input', (e) => {
        let val = parseFloat(e.target.value);
        if (isNaN(val)) return;
        
        // Clamp value inside slider constraints for range element
        const min = parseFloat(slider.min);
        const max = parseFloat(slider.max);
        
        state[stateProp] = val;
        slider.value = Math.min(Math.max(val, min), max);
        updateDashboard();
    });
}

