// --- Detailed Model Breakdown & PPTX Export Functions ---

function updateDetailedModelModal() {
    const result = runEvaluation();
    
    // 1. CapEx Breakdown
    const totalCost = result.totalCost;
    const capexBreakdown = [
        { label: "BIPV 光電建材組件", pct: 45, val: totalCost * 0.45 },
        { label: "主體支架與外牆結構安全工程", pct: 20, val: totalCost * 0.20 },
        { label: "機電系統、逆變器與併網配線", pct: 15, val: totalCost * 0.15 },
        { label: "吊裝重機、鷹架與高空施作防護", pct: 12, val: totalCost * 0.12 },
        { label: "系統設計、申報簽證與行政規費", pct: 8, val: totalCost * 0.08 },
    ];
    if (state.otherCost > 0) {
        capexBreakdown.push({ label: "線補/其他自訂建置成本", pct: 0, val: state.otherCost });
    }
    
    const capexContainer = document.getElementById('capex-breakdown-container');
    if (capexContainer) {
        capexContainer.innerHTML = '';
        const totalCapVal = capexBreakdown.reduce((sum, item) => sum + item.val, 0);
        
        capexBreakdown.forEach(item => {
            const itemPct = totalCapVal > 0 ? (item.val / totalCapVal * 100).toFixed(1) : 0;
            const div = document.createElement('div');
            div.style.marginBottom = '0.85rem';
            div.innerHTML = `
                <div style="display: flex; justify-content: space-between; font-size: 0.82rem; margin-bottom: 0.25rem;">
                    <span style="color: #e5e7eb;">${item.label} (${itemPct}%)</span>
                    <span style="color: #fff; font-weight: 600;">${item.val.toFixed(2)} 萬元</span>
                </div>
                <div style="background: rgba(255,255,255,0.05); height: 6px; border-radius: 3px; overflow: hidden;">
                    <div style="background: #f59e0b; width: ${itemPct}%; height: 100%; border-radius: 3px;"></div>
                </div>
            `;
            capexContainer.appendChild(div);
        });
    }
    
    // 2. OpEx Breakdown (First Year)
    if (result.tableData && result.tableData.length > 0) {
        const firstYear = result.tableData[0];
        const opexBreakdown = [
            { label: "定期維護與機械巡檢費", val: firstYear.omCost },
            { label: "專案營運行政管理費", val: firstYear.overhead },
            { label: "固定台電電錶租金", val: firstYear.meterRent },
            { label: "模組回收準備基金", val: firstYear.recycling },
            { label: "公共意外與財產保險", val: firstYear.insurance },
        ];
        if (state.loanEnable && firstYear.interest > 0) {
            opexBreakdown.push({ label: "銀行融資利息支出", val: firstYear.interest });
        }
        if (firstYear.tax > 0) {
            opexBreakdown.push({ label: "營運所得稅預扣額", val: firstYear.tax });
        }
        
        const opexContainer = document.getElementById('opex-breakdown-container');
        if (opexContainer) {
            opexContainer.innerHTML = '';
            const totalOpVal = opexBreakdown.reduce((sum, item) => sum + item.val, 0);
            
            opexBreakdown.forEach(item => {
                const itemPct = totalOpVal > 0 ? (item.val / totalOpVal * 100).toFixed(1) : 0;
                const div = document.createElement('div');
                div.style.marginBottom = '0.85rem';
                div.innerHTML = `
                    <div style="display: flex; justify-content: space-between; font-size: 0.82rem; margin-bottom: 0.25rem;">
                        <span style="color: #e5e7eb;">${item.label} (${itemPct}%)</span>
                        <span style="color: #fff; font-weight: 600;">${item.val.toFixed(2)} 萬元</span>
                    </div>
                    <div style="background: rgba(255,255,255,0.05); height: 6px; border-radius: 3px; overflow: hidden;">
                        <div style="background: #06b6d4; width: ${itemPct}%; height: 100%; border-radius: 3px;"></div>
                    </div>
                `;
                opexContainer.appendChild(div);
            });
        }
    }
    
    // 3. 20-Year Table
    const tableBody = document.getElementById('detailed-gen-table-body');
    if (tableBody) {
        tableBody.innerHTML = '';
        let cumRevenue = 0;
        result.tableData.forEach(row => {
            cumRevenue += row.revenue;
            const tr = document.createElement('tr');
            tr.style.borderBottom = '1px solid rgba(255, 255, 255, 0.04)';
            const yearDegrad = Math.pow(0.992, row.year - 1);
            const efficiencyPct = (yearDegrad * 100).toFixed(1) + '%';
            const annualYieldKwh = state.capacity * (state.sunHours * 365) * state.generationFactor * yearDegrad;
            
            tr.innerHTML = `
                <td style="padding: 0.5rem; text-align: center; color: #9ca3af;">第 ${row.year} 年</td>
                <td style="padding: 0.5rem; text-align: center; color: #10b981; font-weight: 600;">${efficiencyPct}</td>
                <td style="padding: 0.5rem; text-align: right; font-family: monospace;">${Math.round(annualYieldKwh).toLocaleString()} 度</td>
                <td style="padding: 0.5rem; text-align: right; font-family: monospace;">${row.revenue.toFixed(2)} 萬元</td>
                <td style="padding: 0.5rem; text-align: right; font-family: monospace; color: #f59e0b; font-weight: 600;">${cumRevenue.toFixed(2)} 萬元</td>
            `;
            tableBody.appendChild(tr);
        });
    }
}

function exportDetailedReportToPNG() {
    // Force a fresh calculation run and synchronize all dashboard UI components & modal (進行試算與同步)
    updateDashboard();
    updateDetailedModelModal();
    
    const result = runEvaluation();
    const cityObj = citiesDatabase[state.city];
    const cityName = cityObj ? cityObj.name : "自訂地區";
    const loanAmount = state.loanEnable ? result.totalCost * (state.loanPct / 100) : 0;
    const equityOutlay = result.netCost - loanAmount;
    
    // Define the 4 separate widescreen slides to export
    const slides = [
        { name: "01_評估簡報封面", draw: drawSlide1 },
        { name: "02_設計規格與建置成本", draw: drawSlide2 },
        { name: "03_投資回報與ESG指標", draw: drawSlide4 },
        { name: "04_20年期財務明細摘要", draw: drawSlide5 }
    ];
    
    slides.forEach((slide, index) => {
        setTimeout(() => {
            const canvas = document.createElement("canvas");
            canvas.width = 1800;
            canvas.height = 1020; // 16:9 widescreen
            const ctx = canvas.getContext("2d");
            
            // Double scale for high-definition sharpness
            ctx.scale(2, 2);
            
            // Execute drawing
            slide.draw(ctx, result, cityName, equityOutlay);
            
            // Trigger download
            const filename = `${slide.name}_${state.projectName}_${cityName}.png`;
            const link = document.createElement("a");
            link.download = filename;
            link.href = canvas.toDataURL("image/png");
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            
            if (index === slides.length - 1) {
                alert("已成功匯出全部 4 張高質感簡報報告圖檔 (PNG)！");
            }
        }, index * 250); // Sequential trigger to prevent browser blocks
    });
}

