    // Title
    ctx.fillStyle = '#10b981';
    ctx.font = 'bold 30px "Outfit", "Noto Sans TC", sans-serif';
    ctx.fillText("BIPV 太陽能發電牆效益評估報告", 80, 185);
    
    ctx.fillStyle = '#9ca3af';
    ctx.font = '13px "Outfit", "Noto Sans TC", sans-serif';
    ctx.fillText("BIPV Solar Wall Yield Calculator & Financial Dashboard", 80, 220);
    
