    grad.addColorStop(1, '#06b6d4');
    ctx.strokeStyle = grad;
    ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(80, 245); ctx.lineTo(380, 245); ctx.stroke();
    
    // Project Info card
