function drawSlide5(ctx, result, cityName, equityOutlay) {
    ctx.fillStyle = '#060b13';
    ctx.fillRect(0, 0, 900, 510);
    
    // Header
    ctx.fillStyle = '#10b981';
    ctx.font = 'bold 18px "Outfit", "Noto Sans TC", sans-serif';
    ctx.fillText("20 年期財務明細與現金流量預測 (每五年摘要)", 50, 45);
    
    // Header Logo
    if (logoImage.complete && logoImage.naturalWidth !== 0) {
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(835, 30, 16, 0, Math.PI * 2);
        ctx.fill();
        ctx.save();
        ctx.beginPath();
        ctx.arc(835, 30, 15, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(logoImage, 820, 15, 30, 30);
        ctx.restore();
    }
    
    ctx.fillStyle = '#9ca3af';
    ctx.font = '11px "Outfit", "Noto Sans TC", sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText("BIPV 效益評估報告 | 20年明細表", 805, 42);
    ctx.textAlign = 'left';
    
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(50, 58); ctx.lineTo(850, 58); ctx.stroke();
    
    // Card Box
    ctx.fillStyle = 'rgba(10, 20, 38, 0.4)';
    ctx.beginPath(); ctx.roundRect(50, 78, 800, 385, 10); ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.stroke();
    
    // Table Headers
    ctx.fillStyle = '#9ca3af';
    ctx.font = 'bold 11px "Outfit", "Noto Sans TC", sans-serif';
    const headers = ["期數", "發電效率", "年發電量 (度)", "年度收益 (萬)", "維護成本 (萬)", "稅後淨利 (萬)", "累積流 (不維運)", "累積流 (含維運)", "回收 (不維運)", "回收 (含維運)"];
    headers.forEach((h, idx) => {
        if (idx === 0 || idx === 1) {
            ctx.textAlign = 'center';
            if (idx === 0) ctx.fillText(h, 85, 110);
            if (idx === 1) ctx.fillText(h, 135, 110);
        } else {
            ctx.textAlign = 'right';
            if (idx === 2) ctx.fillText(h, 225, 110);
            if (idx === 3) ctx.fillText(h, 300, 110);
            if (idx === 4) ctx.fillText(h, 375, 110);
            if (idx === 5) ctx.fillText(h, 450, 110);
            if (idx === 6) ctx.fillText(h, 540, 110);
            if (idx === 7) ctx.fillText(h, 630, 110);
            if (idx === 8) ctx.fillText(h, 725, 110);
            if (idx === 9) ctx.fillText(h, 825, 110);
        }
    });
    
    let rowY = 150;
    let cumProjectCF = -result.netCost;
    let cumProjectCFNoOM = -result.netCost;
    
    result.tableData.forEach((row, idx) => {
        const yr = idx + 1;
        cumProjectCF += row.projectCF;
        cumProjectCFNoOM += row.revenue;
        
        if (yr === 1 || yr === 5 || yr === 10 || yr === 15 || yr === 20) {
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(65, rowY + 12);
            ctx.lineTo(835, rowY + 12);
            ctx.stroke();
            
            const yearDegrad = Math.pow(0.992, yr - 1);
            const efficiencyPct = (yearDegrad * 100).toFixed(1) + '%';
            const annualYieldKwh = state.capacity * (state.sunHours * 365) * state.generationFactor * yearDegrad;
            
            // Year
            ctx.fillStyle = '#ffffff';
            ctx.font = '11px "Outfit", "Noto Sans TC", sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText(`第 ${yr} 年`, 85, rowY);
            
            // Efficiency
            ctx.fillStyle = '#10b981';
            ctx.font = 'bold 11px "Outfit", sans-serif';
            ctx.fillText(efficiencyPct, 135, rowY);
            
            // Col 3: Yield
            ctx.fillStyle = '#ffffff';
            ctx.font = '11px "Outfit", sans-serif';
            ctx.textAlign = 'right';
            ctx.fillText(Math.round(annualYieldKwh).toLocaleString() + " 度", 225, rowY);
            
            // Col 4: Revenue
            ctx.fillText(row.revenue.toFixed(2), 300, rowY);
            
            // Col 5: OM Cost
            ctx.fillText(`-${row.omCost.toFixed(2)}`, 375, rowY);
            
            // Col 6: Net income
            ctx.fillText(row.netIncome.toFixed(2), 450, rowY);
            
            // Col 7: Cum CF (No OM)
            ctx.fillStyle = cumProjectCFNoOM >= 0 ? '#34d399' : '#f87171';
            ctx.font = 'bold 11px "Outfit", sans-serif';
            ctx.fillText(cumProjectCFNoOM.toFixed(2) + " 萬", 540, rowY);
            
            // Col 8: Cum CF (With OM)
            ctx.fillStyle = cumProjectCF >= 0 ? '#34d399' : '#f87171';
            ctx.fillText(cumProjectCF.toFixed(2) + " 萬", 630, rowY);
            
            // Col 9: Payback Status (No OM)
            ctx.font = 'bold 10px "Outfit", "Noto Sans TC", sans-serif';
            if (result.paybackWithoutOM !== ">20") {
                if (yr < result.paybackWithoutOM) {
                    ctx.fillStyle = '#f87171'; // Red
                    ctx.fillText("未回收", 725, rowY);
                } else if (yr >= result.paybackWithoutOM && (yr - 5 < result.paybackWithoutOM || yr === 1)) {
                    ctx.fillStyle = '#38bdf8'; // Sky Blue
                    ctx.fillText(`第 ${result.paybackWithoutOM} 年回收`, 725, rowY);
                } else {
                    ctx.fillStyle = '#34d399'; // Green
                    ctx.fillText("已回收", 725, rowY);
                }
            } else {
                ctx.fillStyle = '#f87171';
                ctx.fillText("無法回收", 725, rowY);
            }
            
            // Col 10: Payback Status (With OM)
            if (result.paybackWithOM !== ">20") {
                if (yr < result.paybackWithOM) {
                    ctx.fillStyle = '#f87171'; // Red
                    ctx.fillText("未回收", 825, rowY);
                } else if (yr >= result.paybackWithOM && (yr - 5 < result.paybackWithOM || yr === 1)) {
                    ctx.fillStyle = '#38bdf8'; // Sky Blue
                    ctx.fillText(`第 ${result.paybackWithOM} 年回收`, 825, rowY);
                } else {
                    ctx.fillStyle = '#34d399'; // Green
                    ctx.fillText("已回收", 825, rowY);
                }
            } else {
                ctx.fillStyle = '#f87171';
                ctx.fillText("無法回收", 825, rowY);
            }
            
            rowY += 52;
        }
    });
    
    // Notes
    ctx.textAlign = 'left';
    ctx.fillStyle = '#9ca3af';
    ctx.font = '10px "Outfit", "Noto Sans TC", sans-serif';
    ctx.fillText("註：1. 此表為五年期間節錄，詳細數據請下載 Excel。 2. 系統預設發電效率衰退率為每年 0.8%。", 75, 438);
    ctx.fillText("    3. 模組回收費 (1,000元/kW) 於前 10 年攤提 (如 6.72kW 每年提撥 0.067 萬)，第 11 年起提撥完畢即歸零 (0.000)。", 75, 455);
}

function drawSlide6(ctx, result, cityName, equityOutlay) {
    ctx.fillStyle = '#060b13';
    ctx.fillRect(0, 0, 900, 510);
    
    // Header
    ctx.fillStyle = '#10b981';
    ctx.font = 'bold 18px "Outfit", "Noto Sans TC", sans-serif';
    ctx.fillText("五、 財務效益試算邏輯與會計公式說明", 50, 45);
    
    // Header Logo
    if (logoImage.complete && logoImage.naturalWidth !== 0) {
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(835, 30, 16, 0, Math.PI * 2);
        ctx.fill();
        ctx.save();
        ctx.beginPath();
        ctx.arc(835, 30, 15, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(logoImage, 820, 15, 30, 30);
        ctx.restore();
    }
    
    ctx.fillStyle = '#9ca3af';
    ctx.font = '11px "Outfit", "Noto Sans TC", sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText("BIPV 效益評估報告 | 試算邏輯與公式", 805, 42);
    ctx.textAlign = 'left';
    
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(50, 58); ctx.lineTo(850, 58); ctx.stroke();
    
    // Grid variables
    const cards = [
        {
            title: "1. 投資報酬率 (ROI) 與 內部報酬率 (IRR)",
            color: '#10b981',
            lines: [
                "• ROI = 20年累計淨利 ÷ 實質自籌出資 (實質自籌為扣除補助之出資額)",
                "• IRR (自有) 為以實質自籌出資額作為期初 (第0期) 現金流之折現率",
                "• IRR (融資) 期初為首期自籌出資 (總成本 - 補助 - 貸款)，評估財務槓桿報酬",
                "• 實質自籌出資已自動扣除政府建置補助金與地方額外加碼補貼"
            ]
        },
        {
            title: "2. 年度現金流量 (Cash Flow) 計算邏輯",
            color: '#3b82f6',
            lines: [
                "• 年度現金流 = 稅後淨利 + 設備折舊 - 融資本金償還",
                "• 說明：設備折舊為「非現金支出」，在計算真實現金流時需加回",
                "• 若專案採用銀行貸款融資，則需在各期現金流中扣除償還之貸款本金",
                "• 累積現金流為歷年年度現金流的加總累計值 (期初為負的自籌出資)"
            ]
        },
        {
            title: "3. 模組回收提撥費與折舊攤提規定",
            color: '#06b6d4',
            lines: [
                "• 模組回收準備金為法定費率 (1,000元/kWp) 並在前 10 年分攤攤銷完畢",
                "• 公式: 每年提撥 = (系統容量 kWp × 1,000 元) ÷ 10 年 ÷ 10,000 (萬元)",
                "• 說明: 前10年按年提撥 (負值流出)，第11年起因全數提撥完畢即歸零 (0.00)",
                "• 該回收提撥金在會計上將計入資產殘值，並於設備折舊年限內折舊"
            ]
        },
        {
            title: "4. 綠能發電減碳效益與植樹指標",
            color: '#a7f3d0',
            lines: [
                "• 預估年發電量 = 系統容量 × 立面年日照時數 × 0.95立面折減 × 衰退率",
                "• 20年累計減碳效益 = 20年累積發電總度數 × 0.495 kg/度 (電力係數)",
                "• 年等效植樹貢獻 = 年減碳量 (kg) ÷ 12 kg/棵 (依林務局吸碳量換算)",
                "• 系統預設發電效率衰退率為每年 0.8% (即第 N 年效率為 0.992 的 N-1 次方)"
            ]
        }
    ];
    
    cards.forEach((c, idx) => {
        const col = idx % 2;
        const row = Math.floor(idx / 2);
        const tx = 50 + col * 410;
        const ty = 78 + row * 190;
        
        ctx.fillStyle = 'rgba(10, 20, 38, 0.4)';
        ctx.beginPath(); ctx.roundRect(tx, ty, 390, 175, 8); ctx.fill();
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
        ctx.stroke();
        
        // Card Title
        ctx.fillStyle = c.color;
        ctx.font = 'bold 12px "Outfit", "Noto Sans TC", sans-serif';
        ctx.fillText(c.title, tx + 15, ty + 25);
        
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.04)';
        ctx.beginPath(); ctx.moveTo(tx + 15, ty + 35); ctx.lineTo(tx + 375, ty + 35); ctx.stroke();
        
        // Lines
        ctx.fillStyle = '#d1d5db';
        ctx.font = '10px "Outfit", "Noto Sans TC", sans-serif';
        let ly = ty + 56;
        c.lines.forEach(line => {
            ctx.fillText(line, tx + 15, ly);
            ly += 26;
        });
    });
    
    // Bottom footnote
    ctx.textAlign = 'left';
    ctx.fillStyle = '#9ca3af';
    ctx.font = '10px "Outfit", "Noto Sans TC", sans-serif';
    ctx.fillText("說明：本頁詳述專案會計準則。回收準備金提撥計入資產殘值並於折舊年限 (15年) 內折舊；現金流已扣減融資還本利息，代表稅後淨收益。", 50, 485);
}

function drawSlide7(ctx, result, cityName, equityOutlay) {
    ctx.fillStyle = '#060b13';
    ctx.fillRect(0, 0, 900, 510);
    
    // Header
    ctx.fillStyle = '#10b981';
    ctx.font = 'bold 18px "Outfit", "Noto Sans TC", sans-serif';
    ctx.fillText("六、 20 年期財務明細表各欄位計算公式與邏輯對照", 50, 45);
    
    // Header Logo
    if (logoImage.complete && logoImage.naturalWidth !== 0) {
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(835, 30, 16, 0, Math.PI * 2);
        ctx.fill();
        ctx.save();
        ctx.beginPath();
        ctx.arc(835, 30, 15, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(logoImage, 820, 15, 30, 30);
        ctx.restore();
    }
    
    ctx.fillStyle = '#9ca3af';
    ctx.font = '11px "Outfit", "Noto Sans TC", sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText("BIPV 效益評估報告 | 明細表欄位公式", 805, 42);
    ctx.textAlign = 'left';
    
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(50, 58); ctx.lineTo(850, 58); ctx.stroke();
    
    // Table container background
    ctx.fillStyle = 'rgba(10, 20, 38, 0.4)';
    ctx.beginPath(); ctx.roundRect(50, 78, 800, 385, 8); ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.stroke();
    
    // Table header row background
    ctx.fillStyle = 'rgba(16, 185, 129, 0.08)';
    ctx.beginPath(); ctx.roundRect(52, 80, 796, 26, 4); ctx.fill();
    
    ctx.fillStyle = '#10b981';
    ctx.font = 'bold 11px "Outfit", "Noto Sans TC", sans-serif';
    ctx.fillText("明細表欄位名稱", 70, 97);
    ctx.fillText("對應計算公式與會計科目說明", 250, 97);
    
    const rows = [
        { name: "期數 (年)", formula: "預估之第 1 年至第 20 年運營期。" },
        { name: "營業收入 (售電)", formula: "年預估發電量 (容量 × 日照 × 365天 × 0.95立面折減 × 效率衰退) × 躉購費率 (北部加成 × 1.15)" },
        { name: "1. 維護費用", formula: "營業收入 × 維護費率 (系統依第 1-5 年 / 第 6-20 年之設定費率自動變更計算)" },
        { name: "2. 電錶租金", formula: "自訂月租金 × 12 個月 (例：月租 0.1 萬 ➔ 固定年支出 1.2 萬元)" },
        { name: "3. 回收費用", formula: "前 10 年法定提撥: (系統容量 kWp × 1,000 元) ÷ 10 年 ÷ 10,000 (萬元)；第 11 年起提撥完畢歸零" },
        { name: "4. 設備折舊", formula: "折舊年限內按年攤提，前10年為 (總成本 ÷ 15)；後5年加回提撥回收準備金之折舊額" },
        { name: "5. 營運雜費", formula: "建置總成本 × 營運行政管理費率 (預設 0.30% / 年，主要包含案場行政與場地管理開銷)" },
        { name: "6. 產險費用", formula: "建置總成本 × 固定設備產險費率 (預設 0.35% / 年，主要保障天然災害與設備損壞)" },
        { name: "7. 融資利息", formula: "僅在啟用融資時計算：期初貸款總額餘額 × 貸款年利率 (採本金平均攤還計算)" },
        { name: "稅後淨利", formula: "(營業收入 - 維護費 - 電錶租金 - 回收費 - 雜費 - 產險費 - 利息 - 折舊) × (1 - 營所稅率)；虧損時不計稅" },
        { name: "年度現金流", formula: "稅後淨利 + 設備折舊 (非現金開銷加回) - 融資本本還款 (若有融資，需扣減該期本金還款)" },
        { name: "累積現金流", formula: "歷年「年度現金流」之加總累計 (第 0 期期初金額為負的實質自籌出資或首期自籌出資)" }
    ];
    
    let ry = 125;
    rows.forEach((r, idx) => {
        // Alternating row background
        if (idx % 2 === 1) {
            ctx.fillStyle = 'rgba(255, 255, 255, 0.015)';
            ctx.fillRect(52, ry - 16, 796, 26);
        }
        
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(52, ry + 10); ctx.lineTo(848, ry + 10); ctx.stroke();
        
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 10px "Outfit", "Noto Sans TC", sans-serif';
        ctx.fillText(r.name, 70, ry);
        
        ctx.fillStyle = '#d1d5db';
        ctx.font = '10px "Outfit", "Noto Sans TC", sans-serif';
        ctx.fillText(r.formula, 250, ry);
        
        ry += 28;
    });
    
    // Bottom footnote
    ctx.textAlign = 'left';
    ctx.fillStyle = '#9ca3af';
    ctx.font = '10px "Outfit", "Noto Sans TC", sans-serif';
    ctx.fillText("說明：本頁列出 20 年財務明細表 12 個欄位的計算公式。營業收入已扣減年效率衰退；稅後淨利與年度現金流代表業主實質稅後淨收益。", 50, 485);
}

// Bind Sliders and Text/Number inputs together
document.addEventListener('DOMContentLoaded', () => {
    // 0. Load saved projects list & setup database listeners
    loadSavedProjectsList();
    
    document.getElementById('project-name-input').addEventListener('input', (e) => {
        state.projectName = e.target.value.trim();
    });
    
    document.getElementById('save-project-btn').addEventListener('click', saveCurrentProject);
    document.getElementById('delete-project-btn').addEventListener('click', deleteProjectState);
    document.getElementById('project-select').addEventListener('change', (e) => {
        loadProjectState(e.target.value);
    });

    // 1. Persistent custom regions database load
    loadCustomCities();
    
    // 2. Initialize Presets
    document.getElementById('preset-no-subsidy').addEventListener('click', (e) => {
        document.getElementById('preset-no-subsidy').classList.add('active');
        document.getElementById('preset-with-subsidy').classList.remove('active');
        loadPreset('no-subsidy');
    });
    
    document.getElementById('preset-with-subsidy').addEventListener('click', (e) => {
        document.getElementById('preset-with-subsidy').classList.add('active');
        document.getElementById('preset-no-subsidy').classList.remove('active');
        loadPreset('with-subsidy');
    });
    
    // 3. Bidirectional bind sliders & inputs
    bindInputs('sun-hours', 'sun-hours-num', 'sunHours', 2);
    bindInputs('capacity', 'capacity-num', 'capacity', 2);
    bindInputs('unit-cost', 'unit-cost-num', 'unitCost', 2);
    bindInputs('other-cost', 'other-cost-num', 'otherCost', 2);
    bindInputs('fit-rate', 'fit-rate-num', 'fitRate', 2);
    bindInputs('gen-factor', 'gen-factor-num', 'generationFactor', 2);
    bindInputs('dep-years', 'dep-years-num', 'depreciationYears', 0);
    bindInputs('govt-subsidy', 'govt-subsidy-num', 'govtSubsidy', 2);
    bindInputs('extra-subsidy', 'extra-subsidy-num', 'extraSubsidy', 2);
    bindInputs('meter-rent', 'meter-rent-num', 'meterRent', 2);
    bindInputs('loan-pct', 'loan-pct-num', 'loanPct', 0);
    bindInputs('loan-rate', 'loan-rate-num', 'loanRate', 2);
    bindInputs('loan-years', 'loan-years-num', 'loanYears', 0);
    bindInputs('om-rate-1-5', 'om-rate-1-5-num', 'omRate1_5', 2);
    bindInputs('om-rate-6-20', 'om-rate-6-20-num', 'omRate6_20', 2);
    bindInputs('management-rate', 'management-rate-num', 'managementRate', 2);
    bindInputs('insurance-rate', 'insurance-rate-num', 'insuranceRate', 2);
    bindInputs('recycling-rate', 'recycling-rate-num', 'recyclingRate', 0);
    bindInputs('tax-rate', 'tax-rate-num', 'taxRate', 0);
    
    // 4. Region dropdown handler
    document.getElementById('city-select').addEventListener('change', (e) => {
        const selectedCity = e.target.value;
        state.city = selectedCity;
        
        const cityData = citiesDatabase[selectedCity];
        if (cityData) {
            state.sunHours = cityData.sunHours;
            document.getElementById('sun-hours').value = state.sunHours;
            document.getElementById('sun-hours-num').value = state.sunHours.toFixed(2);
        }
        updateDashboard();
    });
    
    // 5. Custom Region Submission Form
    document.getElementById('add-city-btn').addEventListener('click', () => {
        const nameInput = document.getElementById('custom-city-name');
        const hoursInput = document.getElementById('custom-city-hours');
        const northCheck = document.getElementById('custom-city-north');
        
        const name = nameInput.value.trim();
        const hours = parseFloat(hoursInput.value);
        const isNorthern = northCheck.checked;
        
        if (!name) {
            alert("請輸入地區名稱！");
            return;
        }
        if (isNaN(hours) || hours <= 0 || hours > 12) {
            alert("請輸入合理的日照時數 (如 3.5)！");
            return;
        }
        
        // Add & save
        saveCustomCity(name, hours, isNorthern);
        
        // Reset form
        nameInput.value = '';
        hoursInput.value = '';
        northCheck.checked = false;
        
        alert(`已成功將地區「${name}」儲存至資料庫！`);
    });
    
    // 6. Loan Enable switch
    document.getElementById('loan-enable-toggle').addEventListener('change', (e) => {
        state.loanEnable = e.target.checked;
        toggleLoanControlsVisibility();
        updateDashboard();
    });
    
    // 7. Exporters
    document.getElementById('export-excel-btn').addEventListener('click', exportToExcel);
    document.getElementById('export-png-btn').addEventListener('click', exportToPNG);
    
    // Legacy CSV fallback exporter (wrapped in safety check to prevent crash if button is removed from DOM)
    const csvBtn = document.getElementById('export-csv-btn');
    if (csvBtn) {
        csvBtn.addEventListener('click', () => {
            const result = runEvaluation();
            const cityObj = citiesDatabase[state.city];
            const cityName = cityObj ? cityObj.name : "自訂地區";
            
            let csvContent = "data:text/csv;charset=utf-8,\uFEFF"; 
            csvContent += "期數(年),營業收入(萬元),維護費用(萬元),電錶租金(萬元),模組回收費用(萬元),折舊(萬元),營運管理費(萬元),產險費(萬元),利息支出(萬元),稅後淨利(萬元),年度現金流(萬元)\n";
            
            result.tableData.forEach(row => {
                csvContent += `${row.year},${row.revenue.toFixed(3)},-${row.omCost.toFixed(3)},-${row.meterRent.toFixed(3)},-${row.recycling.toFixed(3)},-${row.dep.toFixed(3)},-${row.overhead.toFixed(3)},-${row.insurance.toFixed(3)},-${row.interest.toFixed(3)},${row.netIncome.toFixed(3)},${row.projectCF.toFixed(3)}\n`;
            });
            
            const encodedUri = encodeURI(csvContent);
            const link = document.createElement("a");
            link.setAttribute("href", encodedUri);
            link.setAttribute("download", `BIPV發電效益報表_${cityName}_${state.capacity}kW.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        });
    }
    
    // 8. Help explanation modal popup handlers (defensively wrapped)
    const modal = document.getElementById('explanation-modal');
    const infoModalBtn = document.getElementById('info-modal-btn');
    const modalCloseBtn = document.getElementById('modal-close-btn');
    
    if (infoModalBtn && modal) {
        infoModalBtn.addEventListener('click', () => {
            modal.style.display = 'flex';
        });
    }
    if (modalCloseBtn && modal) {
        modalCloseBtn.addEventListener('click', () => {
            modal.style.display = 'none';
        });
    }
    
    // 9. Detailed Model modal popup handlers
    const dModal = document.getElementById('detailed-model-modal');
    const dModalBtn = document.getElementById('detailed-model-btn');
    const dModalCloseBtn = document.getElementById('detailed-model-close-btn');
    const dPngBtn = document.getElementById('download-detailed-png-btn');
    
    if (dModalBtn && dModal) {
        dModalBtn.addEventListener('click', () => {
            updateDetailedModelModal();
            dModal.style.display = 'flex';
        });
    }
    if (dModalCloseBtn && dModal) {
        dModalCloseBtn.addEventListener('click', () => {
            dModal.style.display = 'none';
        });
    }
    if (dPngBtn) {
        dPngBtn.addEventListener('click', exportDetailedReportToPNG);
    }
    
    // Close modal if clicked outside
    window.addEventListener('click', (e) => {
        if (modal && e.target === modal) {
            modal.style.display = 'none';
        }
        if (dModal && e.target === dModal) {
            dModal.style.display = 'none';
        }
    });
    
    // Load default preset initially
    loadPreset('no-subsidy');
});
